    def L(number,title,source,category,steps=None,why=None):
        definition=cp(source)
        definition.update(id=1000+number,key='lesson_%02d'%number,title=title,training_category=category,module=source['category'],rewards={'xp':0})
        practical=cp(steps if steps is not None else solutions[int(source['id'])-1])
        nav=[{'event':{'type':'server_selected','host':definition['server']}}]
        tutorial_steps=[step('Otevři správné zařízení','V serverovně klikni na '+definition['server']+'.','Zásah vždy začíná identitou správného zařízení.','rack:'+definition['server'],event=nav[0]['event'],page='Serverovna',tab='')]
        if definition['category']!='Storage':
            nav.append({'event':{'type':'node_selected','host':definition['server']}})
            tutorial_steps.append(step('Vyber hostitele','Ve stromu vyber '+definition['server']+'.','Hostitel a virtuální stroj mají oddělené konfigurační úrovně.','tree:'+definition['server'],event=nav[-1]['event'],page=definition['category'],tab='Podle ticketu'))
        for i,(id,params) in enumerate(practical):
            preferred=definition['category']
            if id=='power' and params.get('vm')=='200': preferred='Hyper-V'
            a=next((x for x in actions if x['id']==id and x.get('console','Proxmox')==preferred),next(x for x in actions if x['id']==id))
            checks=definition['objectives'] if id=='verify' and i==len(practical)-1 else effects(id,params)
            instruction=a['label']+'. '+', '.join(str(k)+' = '+str(v) for k,v in params.items())+'.'
            explanation=(why or {}).get(id,definition['explanations'])
            tutorial_steps.append(step(a['label'],instruction,explanation,'action:'+id,checks,{'type':'action_applied','action':id},page=a.get('console','Proxmox'),tab=a['panel'],error='Konfigurace ještě neodpovídá tomuto kroku. '+instruction))
        definition['steps']=tutorial_steps
        lessons.append(definition); lesson_solutions[str(definition['id'])]=nav+practical
        return definition
