    # The simulation stores disk/storage capacities in laboratory GB; RAM is
    # GiB, with the real 1024 MiB/GiB conversion in EducationOperations.
    for lesson in lessons:
        if lesson['id'] == 1002:
            def disk_units(value):
                if isinstance(value, str): return value.replace('32GiB', '32 GB')
                if isinstance(value, dict): return {k: disk_units(v) for k, v in value.items()}
                if isinstance(value, list): return [disk_units(v) for v in value]
                return value
            lesson.update(disk_units(lesson))
